/**
 * Marker vocabulary for generated artifacts.
 *
 * Default (no marker argument): dto-gen's `@generated` or Ruby `_comment`.
 * External toolchains pass their own substring (e.g. `auto-generated by NAPI-RS`).
 */

export function hasMarker(contents: string, marker?: string): boolean {
  if (marker === undefined) {
    return contents.includes('@generated') || contents.includes('_comment')
  }
  return contents.includes(marker)
}
